def first_versions(apps, schema_editor):
    """Each document already there: its file as version 1."""
    Document = apps.get_model("products", "Document")
    DocumentVersion = apps.get_model("products", "DocumentVersion")

    for document in Document.objects.exclude(file=""):
        version = DocumentVersion.objects.create(
            document=document,
            number=1,
            file=document.file.name,
            file_name=document.file.name.rsplit("/", 1)[-1],
        )
        # The version dated like the document, not like the migration.
        DocumentVersion.objects.filter(pk=version.pk).update(
            added_at=document.added_at
        )
        Document.objects.filter(pk=document.pk).update(version=1)


